{"content": "     1|//! Crystal types — the persistent wisdom unit of CCM.
     2|//!
     3|//! Pure types: no logic, no I/O, no external dependencies beyond serde.
     4|
     5|use serde::{Deserialize, Serialize};
     6|
     7|/// Fibonacci F(8) = 21 — minimum observations before crystallization.
     8|/// Single source of truth — used by both SurrealDB SQL and InMemory adapter.
     9|pub const MIN_CRYSTALLIZATION_CYCLES: u32 = 21;
    10|/// Fibonacci F(13) = 233 — canonical status (deeply crystallized).
    11|pub const CANONICAL_CYCLES: u32 = 233;
    12|/// Max provenance entries per crystal. Prevents unbounded Vec growth on long-lived crystals.
    13|pub const MAX_CONTRIBUTING_VERDICTS: usize = 500;
    14|
    15|// ── CRYSTAL ─────────────────────────────────────────────────
    16|/// A crystallized truth — persistent wisdom extracted from ephemeral verdicts.
    17|#[derive(Debug, Clone, Serialize, Deserialize)]
    18|pub struct Crystal {
    19|    /// Unique identifier
    20|    pub id: String,
    21|    /// The crystallized insight (domain-agnostic)
    22|    pub content: String,
    23|    /// Domain this was crystallized from (e.g. "chess", "code", "general")
    24|    pub domain: String,
    25|    /// Running mean of normalized Q-Score totals (= quality dimension)
    26|    pub confidence: f64,
    27|    /// Number of concordant observations
    28|    pub observations: u32,
    29|    /// Current state in the crystallization lifecycle
    30|    pub state: CrystalState,
    31|    /// Timestamp of creation
    32|    pub created_at: String,
    33|    /// Timestamp of last update
    34|    pub updated_at: String,
    35|    /// Verdict IDs that contributed observations to this crystal (provenance trail).
    36|    /// Enables auditing: "why did this crystal crystallize?" → trace back to verdicts.
    37|    #[serde(default)]
    38|    pub contributing_verdicts: Vec<String>,
    39|
    40|    // ── 4D Crystal Model ──────────────────────────────────────
    41|    // Quality = confidence (above). Certainty + polarity + time below.
    42|    /// Statistical certainty: concordance(Welford) × volume(obs/21).
    43|    /// Crystallization gate uses this, not confidence. Allows negative truths to crystallize.
    44|    #[serde(default)]
    45|    pub certainty: f64,
    46|    /// Welford running M2 — internal state for incremental variance.
    47|    /// stddev = sqrt(variance_m2 / (observations - 1)) when observations > 1.
    48|    #[serde(default)]
    49|    pub variance_m2: f64,
    50|    /// Running mean of voter_count across observations (observability, not gating).
    51|    #[serde(default)]
    52|    pub mean_quorum: f64,
    53|    /// HOWL verdict count — for polarity tracking.
    54|    #[serde(default)]
    55|    pub howl_count: u32,
    56|    /// WAG verdict count.
    57|    #[serde(default)]
    58|    pub wag_count: u32,
    59|    /// GROWL verdict count.
    60|    #[serde(default)]
    61|    pub growl_count: u32,
    62|    /// BARK verdict count.
    63|    #[serde(default)]
    64|    pub bark_count: u32,
    65|
    66|    // ── Mycelium transport ───────────────────────────────────
    67|    /// Sources that have contributed observations to this crystal.
    68|    /// Key = source identifier (e.g. "deterministic-dog", "hermes-agent")
    69|    /// Value = observation count from that source.
    70|    /// BTreeMap for deterministic serialization (K19).
    71|    #[serde(default)]
    72|    pub contributing_sources: std::collections::BTreeMap<String, u32>,
    73|    /// Timestamp when this crystal was shattered (if applicable).
    74|    #[serde(default)]
    75|    pub shattered_at: Option<String>,
    76|    /// Reason for shattering — the catastrophic event.
    77|    #[serde(default)]
    78|    pub shatter_reason: Option<String>,
    79|    /// Source that triggered the shatter.
    80|    #[serde(default)]
    81|    pub shatter_source: Option<String>,
    82|}
    83|
    84|impl Crystal {
    85|    /// Dominant verdict polarity — argmax of the 4 verdict counters.
    86|    /// Returns "HOWL"/"WAG"/"GROWL"/"BARK", or "UNKNOWN" if no observations.
    87|    pub fn dominant_polarity(&self) -> &'static str {
    88|        let counts = [
    89|            (self.howl_count, "HOWL"),
    90|            (self.wag_count, "WAG"),
    91|            (self.growl_count, "GROWL"),
    92|            (self.bark_count, "BARK"),
    93|        ];
    94|        counts
    95|            .iter()
    96|            .max_by_key(|(count, _)| *count)
    97|            .filter(|(count, _)| *count > 0)
    98|            .map(|(_, name)| *name)
    99|            .unwrap_or("UNKNOWN")
   100|    }
   101|
   102|    /// Number of distinct sources that have contributed observations.
   103|    pub fn source_diversity(&self) -> u32 {
   104|        self.contributing_sources.len() as u32
   105|    }
   106|}
   107|
   108|#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
   109|pub enum CrystalState {
   110|    /// Accumulating observations, not yet crystallized (< 21 cycles)
   111|    Forming,
   112|    /// Reached certainty threshold (>= 21 cycles, certainty >= phi-inverse)
   113|    Crystallized,
   114|    /// Reached canonical status (>= 233 cycles, certainty >= phi-inverse)
   115|    Canonical,
   116|    /// Certainty dropped below phi-inverse-squared — decaying
   117|    Decaying,
   118|    /// Fully dissolved — no longer valid wisdom
   119|    Dissolved,
   120|}
   121|
   122|impl std::fmt::Display for CrystalState {
   123|    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
   124|        match self {
   125|            Self::Forming => write!(f, "forming"),
   126|            Self::Crystallized => write!(f, "crystallized"),
   127|            Self::Canonical => write!(f, "canonical"),
   128|            Self::Decaying => write!(f, "decaying"),
   129|            Self::Dissolved => write!(f, "dissolved"),
   130|        }
   131|    }
   132|}
   133|
   134|impl std::str::FromStr for CrystalState {
   135|    type Err = String;
   136|    fn from_str(s: &str) -> Result<Self, Self::Err> {
   137|        match s {
   138|            "forming" => Ok(Self::Forming),
   139|            "crystallized" => Ok(Self::Crystallized),
   140|            "canonical" => Ok(Self::Canonical),
   141|            "decaying" => Ok(Self::Decaying),
   142|            "dissolved" => Ok(Self::Dissolved),
   143|            other => Err(format!("unknown crystal state: {other}")),
   144|        }
   145|    }
   146|}
   147|
   148|// ── MATURE CRYSTAL NEWTYPE (T4) ─────────────────────────────
   149|/// A crystal that has reached Crystallized or Canonical state.
   150|/// Private inner field — can only be constructed via `TryFrom<Crystal>`,
   151|/// which validates the state at compile-time boundary. This prevents
   152|/// Forming/Decaying/Dissolved crystals from reaching Dog prompts.
   153|#[derive(Debug, Clone)]
   154|pub struct MatureCrystal {
   155|    inner: Crystal,
   156|}
   157|
   158|/// Error when attempting to create a MatureCrystal from a non-mature Crystal.
   159|#[derive(Debug)]
   160|pub struct NotMatureError {
   161|    pub id: String,
   162|    pub state: CrystalState,
   163|}
   164|
   165|impl std::fmt::Display for NotMatureError {
   166|    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
   167|        write!(f, "crystal '{}' is {:?}, not mature", self.id, self.state)
   168|    }
   169|}
   170|
   171|impl std::error::Error for NotMatureError {}
   172|
   173|impl TryFrom<Crystal> for MatureCrystal {
   174|    type Error = NotMatureError;
   175|
   176|    fn try_from(crystal: Crystal) -> Result<Self, Self::Error> {
   177|        match crystal.state {
   178|            CrystalState::Crystallized | CrystalState::Canonical => {
   179|                Ok(MatureCrystal { inner: crystal })
   180|            }
   181|            _ => Err(NotMatureError {
   182|                id: crystal.id.clone(),
   183|                state: crystal.state,
   184|            }),
   185|        }
   186|    }
   187|}
   188|
   189|impl MatureCrystal {
   190|    /// Access the underlying Crystal (read-only).
   191|    pub fn crystal(&self) -> &Crystal {
   192|        &self.inner
   193|    }
   194|
   195|    pub fn id(&self) -> &str {
   196|        &self.inner.id
   197|    }
   198|
   199|    pub fn content(&self) -> &str {
   200|        &self.inner.content
   201|    }
   202|
   203|    pub fn domain(&self) -> &str {
   204|        &self.inner.domain
   205|    }
   206|
   207|    pub fn confidence(&self) -> f64 {
   208|        self.inner.confidence
   209|    }
   210|
   211|    pub fn observations(&self) -> u32 {
   212|        self.inner.observations
   213|    }
   214|
   215|    pub fn state(&self) -> &CrystalState {
   216|        &self.inner.state
   217|    }
   218|
   219|    pub fn updated_at(&self) -> &str {
   220|        &self.inner.updated_at
   221|    }
   222|
   223|    pub fn certainty(&self) -> f64 {
   224|        self.inner.certainty
   225|    }
   226|
   227|    pub fn dominant_polarity(&self) -> &'static str {
   228|        self.inner.dominant_polarity()
   229|    }
   230|}
   231|
   232|/// Filter a list of Crystals into only mature ones.
   233|/// Convenience function — equivalent to try_from + filter_map.
   234|pub fn filter_mature(crystals: Vec<Crystal>) -> Vec<MatureCrystal> {
   235|    crystals
   236|        .into_iter()
   237|        .filter_map(|c| MatureCrystal::try_from(c).ok())
   238|        .collect()
   239|}
   240|
   241|// ── TESTS ───────────────────────────────────────────────────
   242|#[cfg(test)]
   243|mod tests {
   244|    use super::*;
   245|    use crate::domain::dog::PHI_INV;
   246|
   247|    fn make_crystal(confidence: f64, observations: u32, state: CrystalState) -> Crystal {
   248|        Crystal {
   249|            id: "test-1".into(),
   250|            content: "test pattern".into(),
   251|            domain: "test".into(),
   252|            confidence,
   253|            observations,
   254|            state,
   255|            created_at: "2026-03-13T00:00:00Z".into(),
   256|            updated_at: "2026-03-13T00:00:00Z".into(),
   257|            contributing_verdicts: vec![],
   258|            certainty: 0.0,
   259|            variance_m2: 0.0,
   260|            mean_quorum: 0.0,
   261|            howl_count: 0,
   262|            wag_count: 0,
   263|            growl_count: 0,
   264|            bark_count: 0,
   265|            contributing_sources: std::collections::BTreeMap::new(),
   266|            shattered_at: None,
   267|            shatter_reason: None,
   268|            shatter_source: None,
   269|        }
   270|    }
   271|
   272|    #[test]
   273|    fn mature_crystal_rejects_forming() {
   274|        let forming = make_crystal(0.5, 5, CrystalState::Forming);
   275|        assert!(MatureCrystal::try_from(forming).is_err());
   276|    }
   277|
   278|    #[test]
   279|    fn mature_crystal_accepts_crystallized() {
   280|        let crystallized = make_crystal(PHI_INV, 25, CrystalState::Crystallized);
   281|        assert!(MatureCrystal::try_from(crystallized).is_ok());
   282|    }
   283|
   284|    #[test]
   285|    fn mature_crystal_accepts_canonical() {
   286|        let canonical = make_crystal(PHI_INV, 250, CrystalState::Canonical);
   287|        assert!(MatureCrystal::try_from(canonical).is_ok());
   288|    }
   289|
   290|    #[test]
   291|    fn mature_crystal_rejects_decaying() {
   292|        let decaying = make_crystal(0.2, 30, CrystalState::Decaying);
   293|        assert!(MatureCrystal::try_from(decaying).is_err());
   294|    }
   295|
   296|    #[test]
   297|    fn crystal_state_display_is_lowercase() {
   298|        assert_eq!(CrystalState::Forming.to_string(), "forming");
   299|        assert_eq!(CrystalState::Crystallized.to_string(), "crystallized");
   300|        assert_eq!(CrystalState::Canonical.to_string(), "canonical");
   301|        assert_eq!(CrystalState::Decaying.to_string(), "decaying");
   302|        assert_eq!(CrystalState::Dissolved.to_string(), "dissolved");
   303|    }
   304|
   305|    #[test]
   306|    fn crystal_state_round_trip() {
   307|        for state in [
   308|            CrystalState::Forming,
   309|            CrystalState::Crystallized,
   310|            CrystalState::Canonical,
   311|            CrystalState::Decaying,
   312|            CrystalState::Dissolved,
   313|        ] {
   314|            let s = state.to_string();
