{"content": "     1|//! Embedding adapter — calls any OpenAI-compatible /v1/embeddings endpoint.
     2|//! Default target: local llama-server on :8081 with Qwen3-Embedding.
     3|
     4|use crate::domain::embedding::{Embedding, EmbeddingError, EmbeddingPort};
     5|use crate::domain::inference::{BackendPort, BackendStatus};
     6|use async_trait::async_trait;
     7|use reqwest::Client;
     8|use serde::{Deserialize, Serialize};
     9|use std::time::Instant;
    10|
    11|#[derive(Debug)]
    12|pub struct EmbeddingBackend {
    13|    client: Client,
    14|    base_url: String,
    15|    api_key: Option<String>,
    16|    model: String,
    17|}
    18|
    19|impl EmbeddingBackend {
    20|    pub fn new(
    21|        base_url: &str,
    22|        api_key: Option<String>,
    23|        model: &str,
    24|    ) -> Result<Self, crate::domain::inference::BackendInitError> {
    25|        Ok(Self {
    26|            client: Client::builder()
    27|                .timeout(std::time::Duration::from_secs(30))
    28|                .build()
    29|                .map_err(crate::domain::inference::BackendInitError::from_http)?,
    30|            base_url: base_url.trim_end_matches('/').to_string(),
    31|            api_key,
    32|            model: model.to_string(),
    33|        })
    34|    }
    35|
    36|    /// Accessor for logging — base_url is private (encapsulation).
    37|    pub fn base_url(&self) -> &str {
    38|        &self.base_url
    39|    }
    40|
    41|    /// Probe known embedding ports and return the first reachable one.
    42|    /// Order: CYNIC_EMBED_PORT (or 8081 default) → 8080 (shared with inference).
    43|    /// Called at boot and by background discovery task.
    44|    pub async fn discover(host: &str, api_key: Option<String>, model: &str) -> Option<Self> {
    45|        let ports = [
    46|            std::env::var("CYNIC_EMBED_PORT").unwrap_or_else(|_| "8081".into()),
    47|            "8080".into(),
    48|        ];
    49|        let client = Client::builder()
    50|            .timeout(std::time::Duration::from_secs(3))
    51|            .build()
    52|            .ok()?;
    53|
    54|        for port in &ports {
    55|            let base_url = format!("http://{host}:{port}/v1");
    56|            let health_url = format!("http://{host}:{port}/health");
    57|            let mut req = client.get(&health_url);
    58|            if let Some(ref key) = api_key {
    59|                req = req.header("Authorization", format!("Bearer {key}"));
    60|            }
    61|            match tokio::time::timeout(std::time::Duration::from_secs(3), req.send()).await {
    62|                Ok(Ok(resp)) if resp.status().is_success() => {
    63|                    klog!("[Embedding] discovered server at {}:{}", host, port);
    64|                    return Self::new(&base_url, api_key, model)
    65|                        .map_err(|e| klog!("[Embedding] init failed on {}:{}: {}", host, port, e))
    66|                        .ok(); // R2: error logged in map_err above
    67|                }
    68|                _ => {
    69|                    klog!(
    70|                        "[Embedding] port {} unreachable on {}, trying next",
    71|                        port,
    72|                        host
    73|                    );
    74|                    continue;
    75|                }
    76|            }
    77|        }
    78|        None
    79|    }
    80|
    81|    /// Build from environment variables.
    82|    /// CYNIC_EMBED_URL overrides, else derives from CYNIC_REST_ADDR host + port 8081.
    83|    pub fn from_env() -> Result<Self, crate::domain::inference::BackendInitError> {
    84|        let base_url = std::env::var("CYNIC_EMBED_URL").unwrap_or_else(|_| {
    85|            let rest = std::env::var("CYNIC_REST_ADDR")
    86|                .unwrap_or_else(|_| crate::domain::constants::DEFAULT_REST_ADDR.into());
    87|            let host = rest.split(':').next().unwrap_or("127.0.0.1");
    88|            let port = std::env::var("CYNIC_EMBED_PORT").unwrap_or_else(|_| "8081".into());
    89|            format!("http://{host}:{port}/v1")
    90|        });
    91|        let api_key = std::env::var("SOVEREIGN_API_KEY").ok();
    92|        let model = std::env::var("CYNIC_EMBED_MODEL").unwrap_or_else(|_| "qwen3-embed".into());
    93|        Self::new(&base_url, api_key, &model)
    94|    }
    95|}
    96|
    97|#[async_trait]
    98|impl BackendPort for EmbeddingBackend {
    99|    fn name(&self) -> &str {
   100|        &self.model
   101|    }
   102|
   103|    async fn health(&self) -> BackendStatus {
   104|        let start = Instant::now();
   105|        let url = self.base_url.replace("/v1", "/health");
   106|        match self.client.get(&url).send().await {
   107|            Ok(resp) if resp.status().is_success() => {
   108|                let latency = start.elapsed().as_millis() as f64;
   109|                if latency > 2000.0 {
   110|                    BackendStatus::Degraded {
   111|                        latency_ms: latency,
   112|                    }
   113|                } else {
   114|                    BackendStatus::Healthy
   115|                }
   116|            }
   117|            Ok(resp) => {
   118|                tracing::warn!(status = %resp.status(), "embedding backend degraded");
   119|                BackendStatus::Degraded {
   120|                    latency_ms: start.elapsed().as_millis() as f64,
   121|                }
   122|            }
   123|            Err(e) => {
   124|                tracing::error!(error = %e, "embedding backend unreachable — critical");
   125|                BackendStatus::Critical
   126|            }
   127|        }
   128|    }
   129|}
   130|
   131|#[derive(Serialize)]
   132|struct EmbeddingRequest {
   133|    input: String,
   134|    model: String,
   135|}
   136|
   137|#[derive(Deserialize)]
   138|struct EmbeddingResponse {
   139|    data: Vec<EmbeddingData>,
   140|    usage: Option<EmbeddingUsage>,
   141|}
   142|
   143|#[derive(Deserialize)]
   144|struct EmbeddingData {
   145|    embedding: Vec<f32>,
   146|}
   147|
   148|#[derive(Deserialize)]
   149|struct EmbeddingUsage {
   150|    #[serde(default)]
   151|    prompt_tokens: u32,
   152|}
   153|
   154|#[async_trait]
   155|impl EmbeddingPort for EmbeddingBackend {
   156|    async fn embed(&self, text: &str) -> Result<Embedding, EmbeddingError> {
   157|        let url = format!("{}/embeddings", self.base_url);
   158|        let start = Instant::now();
   159|
   160|        let req_body = EmbeddingRequest {
   161|            input: text.to_string(),
   162|            model: self.model.clone(),
   163|        };
   164|
   165|        let mut req = self.client.post(&url).json(&req_body);
   166|
   167|        if let Some(ref key) = self.api_key {
   168|            req = req.header("Authorization", format!("Bearer {key}"));
   169|        }
   170|
   171|        let resp = req.send().await.map_err(|e| {
   172|            if e.is_timeout() {
   173|                EmbeddingError::Timeout {
   174|                    ms: start.elapsed().as_millis() as u64,
   175|                }
   176|            } else {
   177|                EmbeddingError::Unreachable(e.to_string())
   178|            }
   179|        })?;
   180|
   181|        if !resp.status().is_success() {
   182|            let status = resp.status();
   183|            let body = resp.text().await.unwrap_or_default();
   184|            return Err(EmbeddingError::Protocol(format!("HTTP {status}: {body}")));
   185|        }
   186|
   187|        let parsed: EmbeddingResponse = resp
   188|            .json()
   189|            .await
   190|            .map_err(|e| EmbeddingError::Protocol(format!("JSON parse error: {e}")))?;
   191|
   192|        let data = parsed
   193|            .data
   194|            .into_iter()
   195|            .next()
   196|            .ok_or_else(|| EmbeddingError::Protocol("empty response".into()))?;
   197|
   198|        let dimensions = data.embedding.len();
   199|        let prompt_tokens = parsed.usage.map(|u| u.prompt_tokens).unwrap_or(0);
   200|
   201|        Ok(Embedding {
   202|            vector: data.embedding,
   203|            dimensions,
   204|            prompt_tokens,
   205|        })
   206|    }
   207|}
   208|
   209|#[cfg(test)]
   210|mod tests {
   211|    use super::*;
   212|
   213|    #[test]
   214|    fn from_env_defaults() {
   215|        let backend = EmbeddingBackend::from_env().unwrap();
   216|        assert!(backend.base_url().contains("8081"));
   217|        // model field is private — base_url() confirms defaults are applied.
   218|    }
