{"content": "     1|//! AutoRecoveryEmbedding — infra wrapper that hot-swaps embedding backends at runtime.
     2|//! Lives in backends/ (infra layer) because it depends on tokio::sync::RwLock (K5).
     3|
     4|use std::sync::Arc;
     5|
     6|use async_trait::async_trait;
     7|use tokio::sync::RwLock;
     8|
     9|use crate::domain::embedding::{Embedding, EmbeddingError, EmbeddingPort};
    10|
    11|/// Wraps an EmbeddingPort that can be hot-swapped at runtime.
    12|/// Starts with NullEmbedding, upgrades to real backend when discovered.
    13|pub struct AutoRecoveryEmbedding {
    14|    inner: RwLock<Arc<dyn EmbeddingPort>>,
    15|}
    16|
    17|impl std::fmt::Debug for AutoRecoveryEmbedding {
    18|    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
    19|        f.debug_struct("AutoRecoveryEmbedding").finish()
    20|    }
    21|}
    22|
    23|impl AutoRecoveryEmbedding {
    24|    pub fn new(initial: Arc<dyn EmbeddingPort>) -> Self {
    25|        Self {
    26|            inner: RwLock::new(initial),
    27|        }
    28|    }
    29|
    30|    /// Hot-swap the inner backend. Called by discovery loop.
    31|    pub async fn upgrade(&self, backend: Arc<dyn EmbeddingPort>) {
    32|        let mut guard = self.inner.write().await;
    33|        *guard = backend;
    34|    }
    35|}
    36|
    37|#[async_trait]
    38|impl EmbeddingPort for AutoRecoveryEmbedding {
    39|    async fn embed(&self, text: &str) -> Result<Embedding, EmbeddingError> {
    40|        let guard = self.inner.read().await;
    41|        guard.embed(text).await
    42|    }
    43|
    44|    async fn embed_batch(&self, texts: &[&str]) -> Result<Vec<Embedding>, EmbeddingError> {
    45|        let guard = self.inner.read().await;
    46|        guard.embed_batch(texts).await
    47|    }
    48|}
    49|
    50|#[cfg(test)]
    51|mod tests {
    52|    use super::*;
    53|    use crate::domain::embedding::{FixedEmbedding, NullEmbedding};
    54|
    55|    #[tokio::test]
    56|    async fn starts_null_then_upgrades() {
    57|        let auto = AutoRecoveryEmbedding::new(Arc::new(NullEmbedding));
    58|        assert!(auto.embed("test").await.is_err());
    59|
    60|        let fixed = Arc::new(FixedEmbedding::new(vec![1.0, 0.0, 0.0]));
    61|        auto.upgrade(fixed).await;
    62|
    63|        let result = auto.embed("test").await.unwrap();
    64|        assert_eq!(result.dimensions, 3);
    65|    }
    66|
    67|    #[tokio::test]
    68|    async fn double_upgrade_uses_latest() {
    69|        let auto = AutoRecoveryEmbedding::new(Arc::new(NullEmbedding));
    70|        auto.upgrade(Arc::new(FixedEmbedding::new(vec![1.0, 0.0])))
    71|            .await;
    72|        auto.upgrade(Arc::new(FixedEmbedding::new(vec![1.0, 0.0, 0.0, 0.0])))
    73|            .await;
    74|
    75|        let result = auto.embed("test").await.unwrap();
    76|        assert_eq!(result.dimensions, 4);
    77|    }
