   416|    fn epistemic_gate_real_world_disagreement_passes() {
   417|        // Observed: USDC disagreement = 0.568, rug-pull = 0.468
   418|        // Both should now be "disputed" (not quarantined)
   419|        let (tag_usdc, weight_usdc) = epistemic_gate(0.568);
   420|        assert_eq!(tag_usdc, "disputed");
   421|        assert!(
   422|            weight_usdc > 0.0,
