   434|    // ── crystal_confidence normalization (P1 ACCURACY) ──────
   435|
   436|    #[test]
   437|    fn crystal_confidence_howl_reaches_crystallization_threshold() {
   438|        // HOWL verdict: Q-Score at φ-max (0.618) in chess domain (p50=0.549).
   439|        // domain_normalized = min(0.618 / 0.549, 1.0) = 1.0
   440|        // crystal_confidence = 1.0 * PHI_INV * 1.0 = 0.618 = PHI_INV (ceiling)
   441|        let total = PHI_INV;
   442|        let weight = 1.0;
   443|        let normalized = domain_specific_q_normalization(total, "chess");
   444|        let conf = (normalized * PHI_INV * weight).min(PHI_INV);
   445|        assert!(
   446|            conf >= PHI_INV - 1e-10,
   447|            "HOWL verdict should produce crystal_confidence = φ⁻¹ (ceiling), got {conf}"
   448|        );
   449|    }
