   452|    fn crystal_confidence_bark_stays_below_crystallization() {
   453|        // BARK verdict: Q-Score = 0.2 in chess domain (p50=0.549).
   454|        // domain_normalized = 0.2 / 0.549 = 0.364
   455|        // crystal_confidence = 0.364 * 0.618 * 1.0 = 0.225 < PHI_INV
