{"content": "     1|//! Pipeline maintenance — background tasks that run independently of the judge flow.
     2|//! Split from mod.rs per K16: the hot eval path should not carry maintenance code.
     3|
     4|use crate::domain::ccm;
     5|use crate::domain::embedding::EmbeddingPort;
     6|use crate::domain::metrics::Metrics;
     7|use crate::domain::storage::StoragePort;
     8|
     9|// ── CRYSTAL EMBEDDING BACKFILL ────────────────────────────
    10|
    11|/// Backfill embeddings for crystals that were created without one.
    12|/// Crystals without embeddings are permanently invisible to KNN search,
    13|/// meaning they can never be merged or retrieved semantically — orphans forever.
    14|/// Returns the number of crystals successfully embedded.
    15|pub async fn backfill_crystal_embeddings(
    16|    storage: &dyn StoragePort,
    17|    embedding: &dyn EmbeddingPort,
    18|    metrics: &Metrics,
    19|) -> u32 {
    20|    let orphans = match storage.list_crystals_missing_embedding(200).await {
    21|        Ok(c) => c,
    22|        Err(e) => {
    23|            tracing::warn!(error = %e, "backfill: failed to query crystals missing embedding");
    24|            return 0;
    25|        }
    26|    };
    27|    if orphans.is_empty() {
    28|        tracing::info!(phase = "backfill", "no crystals missing embeddings");
    29|        return 0;
    30|    }
    31|    tracing::info!(
    32|        phase = "backfill",
    33|        count = orphans.len(),
    34|        "found crystals missing embeddings"
    35|    );
    36|
    37|    let mut success = 0u32;
    38|    let mut failed = 0u32;
    39|    for crystal in &orphans {
    40|        match embedding.embed(&crystal.content).await {
    41|            Ok(emb) => {
    42|                if let Err(e) = storage
    43|                    .store_crystal_embedding(&crystal.id, &emb.vector)
    44|                    .await
    45|                {
    46|                    tracing::warn!(phase = "backfill", crystal_id = %crystal.id, error = %e, "failed to store embedding");
    47|                    failed += 1;
    48|                } else {
    49|                    metrics.inc_embed_ok();
    50|                    success += 1;
    51|                }
    52|            }
    53|            Err(e) => {
    54|                tracing::warn!(phase = "backfill", crystal_id = %crystal.id, error = %e, "embedding failed");
    55|                metrics.inc_embed_fail();
    56|                failed += 1;
    57|            }
    58|        }
    59|        // Rate-limit HNSW index writes: 50ms between each prevents SurrealKV
    60|        // compaction conflicts from burst pressure at boot (176 conflicts/24h root cause).
    61|        tokio::time::sleep(std::time::Duration::from_millis(50)).await;
    62|    }
    63|    tracing::info!(
    64|        phase = "backfill",
    65|        success = success,
    66|        failed = failed,
    67|        "backfill complete"
    68|    );
    69|    success
    70|}
    71|
    72|// ── SESSION SUMMARIZATION PIPELINE ──────────────────────
    73|
    74|/// Summarize sessions that have observations but no summary yet.
    75|/// Takes port traits — testable with NullStorage + NullSummarizer.
    76|/// Returns the number of sessions successfully summarized.
    77|pub async fn summarize_pending_sessions(
    78|    storage: &dyn StoragePort,
    79|    summarizer: &dyn crate::domain::summarization::SummarizationPort,
    80|) -> u32 {
    81|    let pending = match storage.get_unsummarized_sessions(3, 5).await {
    82|        Ok(p) => p,
    83|        Err(e) => {
    84|            tracing::warn!(error = %e, "failed to query unsummarized sessions");
    85|            return 0;
    86|        }
    87|    };
    88|
    89|    if pending.is_empty() {
    90|        return 0;
    91|    }
    92|
    93|    let mut count = 0u32;
    94|    for (session_id, agent_id, obs_count) in &pending {
    95|        let observations = match storage.get_session_observations(session_id).await {
    96|            Ok(obs) => obs,
    97|            Err(e) => {
    98|                tracing::warn!(session_id = %session_id, error = %e, "failed to get session observations");
    99|                continue;
   100|            }
   101|        };
   102|        if observations.is_empty() {
   103|            continue;
   104|        }
   105|
   106|        let prompt = ccm::format_summarization_prompt(&observations);
   107|        let summary_text = match summarizer.summarize(&prompt).await {
   108|            Ok(text) => text,
   109|            Err(e) => {
   110|                tracing::warn!(session_id = %session_id, error = %e, "session summarization failed");
   111|                continue;
   112|            }
   113|        };
   114|
   115|        let summary = ccm::SessionSummary {
   116|            session_id: session_id.clone(),
   117|            agent_id: agent_id.clone(),
   118|            summary: summary_text,
   119|            observations_count: *obs_count,
   120|            created_at: chrono::Utc::now().to_rfc3339(),
   121|        };
   122|        if let Err(e) = storage.store_session_summary(&summary).await {
   123|            tracing::warn!(session_id = %session_id, error = %e, "failed to store session summary");
   124|        } else {
   125|            count += 1;
   126|        }
   127|    }
   128|
   129|    count
   130|}
   131|
   132|#[cfg(test)]
   133|mod tests {
   134|    use super::*;
   135|    use crate::domain::storage::NullStorage;
   136|    use crate::domain::summarization::NullSummarizer;
   137|
   138|    #[tokio::test]
   139|    async fn summarize_pending_sessions_with_null_deps_returns_zero() {
   140|        let count = summarize_pending_sessions(&NullStorage, &NullSummarizer).await;
   141|        assert_eq!(count, 0, "NullStorage has no pending sessions");
   142|    }
   143|}
   144|", "total_lines": 143, "file_size": 5079, "truncated": false, "is_binary": false, "is_image": false}

