   140|            "canonical" => Ok(Self::Canonical),
   141|            "decaying" => Ok(Self::Decaying),
   142|            "dissolved" => Ok(Self::Dissolved),
   143|            other => Err(format!("unknown crystal state: {other}")),
   144|        }
   145|    }
   146|}
   147|
   148|// ── MATURE CRYSTAL NEWTYPE (T4) ─────────────────────────────
   149|/// A crystal that has reached Crystallized or Canonical state.
   150|/// Private inner field — can only be constructed via `TryFrom<Crystal>`,
   151|/// which validates the state at compile-time boundary. This prevents
   152|/// Forming/Decaying/Dissolved crystals from reaching Dog prompts.
   153|#[derive(Debug, Clone)]
   154|pub struct MatureCrystal {
   155|    inner: Crystal,
   156|}
   157|
   158|/// Error when attempting to create a MatureCrystal from a non-mature Crystal.
   159|#[derive(Debug)]
   160|pub struct NotMatureError {
   161|    pub id: String,
   162|    pub state: CrystalState,
   163|}
   164|
   165|impl std::fmt::Display for NotMatureError {
   166|    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
   167|        write!(f, "crystal '{}' is {:?}, not mature", self.id, self.state)
   168|    }
   169|}
   170|
   171|impl std::error::Error for NotMatureError {}
   172|
   173|impl TryFrom<Crystal> for MatureCrystal {
   174|    type Error = NotMatureError;
   175|
   176|    fn try_from(crystal: Crystal) -> Result<Self, Self::Error> {
   177|        match crystal.state {
   178|            CrystalState::Crystallized | CrystalState::Canonical => {
   179|                Ok(MatureCrystal { inner: crystal })
   180|            }
   181|            _ => Err(NotMatureError {
   182|                id: crystal.id.clone(),
   183|                state: crystal.state,
   184|            }),
   185|        }
   186|    }
   187|}
   188|
   189|impl MatureCrystal {
   190|    /// Access the underlying Crystal (read-only).
   191|    pub fn crystal(&self) -> &Crystal {
   192|        &self.inner
   193|    }
   194|
   195|    pub fn id(&self) -> &str {
   196|        &self.inner.id
   197|    }
   198|
   199|    pub fn content(&self) -> &str {
   200|        &self.inner.content
   201|    }
   202|
   203|    pub fn domain(&self) -> &str {
   204|        &self.inner.domain
   205|    }
   206|
   207|    pub fn confidence(&self) -> f64 {
