   211|    pub fn observations(&self) -> u32 {
   212|        self.inner.observations
   213|    }
   214|
   215|    pub fn state(&self) -> &CrystalState {
   216|        &self.inner.state
   217|    }
   218|
   219|    pub fn updated_at(&self) -> &str {
   220|        &self.inner.updated_at
