{"content": "     1|//! Crystal observation from verdicts — the critical link in the compound loop.
     2|//!
     3|//! Extracted from pipeline.rs: epistemic gating + crystal observation logic.
     4|//! Called on BOTH cache hits and full evaluations.
     5|
     6|use crate::domain::ccm;
     7|use crate::domain::dog::{PHI_INV, PHI_INV2};
     8|use crate::domain::embedding::Embedding;
     9|use crate::domain::events::KernelEvent;
    10|
    11|use super::PipelineDeps;
    12|
    13|/// Whitelist of domains whose content should crystallize.
    14|///
    15|/// Only domains containing EXTERNAL content (tokens, tweets, game positions)
    16|/// crystallize. Internal domains (dev commits, session logs, kernel ops) are
    17|/// judged by nightshift (verdicts count for metrics) but do NOT form crystals.
    18|///
    19|/// CHAOS: start strict, loosen with measurement.
    20|/// Falsify: if crystal A/B test shows dev-domain crystals improve judgment,
    21|/// add "dev" here. Until measured, the principle of precaution applies.
    22|fn is_crystallizable_domain(domain: &str) -> bool {
    23|    matches!(
    24|        domain,
    25|        "chess"
    26|            | "token-analysis"
    27|            | "token"
    28|            | "twitter"
    29|            | "D1"
    30|            | "D2"
    31|            | "D3"
    32|            | "D4"
    33|            | "D5"
    34|            | "D6"
    35|            | "D7"
    36|            | "D8"
    37|            | "D9"
    38|            | "hermes"
    39|            | "governance"
    40|    )
    41|}
    42|
    43|/// Compute epistemic injection weight from Dog disagreement level.
    44|///
    45|/// Returns `(tag, weight)` where tag is "agreed"/"disputed"/"contested"
    46|/// and weight is in [0.0, 1.0]. Pure function — no side effects.
    47|///
    48|/// Thresholds widened (2026-04-26): structural divergence between qwen7b and
    49|/// qwen35 produces per-axiom spreads of 0.4–0.6 on legitimate tokens. The
    50|/// original φ⁻² (0.382) contested gate quarantined >80% of verdicts, starving
    51|/// the CCM of observations. New gate uses φ⁻¹ (0.618) — philosophically
    52|/// consistent: only quarantine disagreement beyond max-confidence ceiling.
    53|///
    54|///   - Agreed   (disagree < φ⁻²): full weight (1.0)
    55|///   - Disputed (φ⁻² ≤ disagree < φ⁻¹): linear decay 1.0→0.0
    56|///   - Contested (disagree ≥ φ⁻¹): quarantined — zero crystal update
    57|pub(crate) fn epistemic_gate(max_disagreement: f64) -> (&'static str, f64) {
    58|    if max_disagreement < PHI_INV2 {
    59|        ("agreed", 1.0)
    60|    } else if max_disagreement < PHI_INV {
    61|        // Linear decay from 1.0 (at φ⁻²) to 0.0 (at φ⁻¹)
    62|        let range = PHI_INV - PHI_INV2;
    63|        let position = max_disagreement - PHI_INV2;
    64|        ("disputed", (1.0 - position / range).max(0.0))
    65|    } else {
    66|        ("contested", 0.0)
    67|    }
    68|}
    69|
    70|/// Domain-specific Q-score calibration. Maps raw Q-scores to [0, 1] range
    71|/// based on domain's observed percentile distribution (2026-05-12 organism audit).
    72|///
    73|/// Problem: Raw Q-scores vary by domain (chess p50=0.549 vs twitter p50=0.249).
    74|/// Without calibration, the same threshold (φ⁻¹=0.618) unfairly gates all domains.
    75|/// Solution: Use domain percentiles to normalize Q-scores so p50 → 0.5 for all domains.
    76|///
    77|/// Percentiles derived from 120K+ observations, 13K verdicts (2026-05-12):
    78|/// - chess          (p50=0.549, p95=0.611) — high variance, mostly repeatable positions
    79|/// - token-analysis (p50=0.333, p95=0.468) — lower variance, diverse tokens
    80|/// - twitter        (p50=0.249, p95=0.387) — lowest, social media noise
    81|/// - dev            (p50=0.380, p95=0.510) — estimated from git commit variability
    82|/// - general        (p50=0.300, p95=0.420) — fallback for unmapped domains
    83|///
    84|/// Calibration formula: `normalized_q = (raw_q / domain_p50).min(1.0)`
    85|/// Maps p50 → 0.5, p95 → ~1.0 (clamped), preserving relative signal.
    86|/// The caller scales the result by PHI_INV to restore the absolute epistemic ceiling.
    87|fn domain_specific_q_normalization(raw_q: f64, domain: &str) -> f64 {
    88|    let domain_p50 = match domain {
    89|        "chess" => 0.549,
    90|        "token" | "token-analysis" => 0.333,
    91|        "twitter" => 0.249,
    92|        "dev" => 0.380,
    93|        "ops" => 0.300,     // kernel/infra observations — new domain, estimate
    94|        "session" => 0.350, // session compliance/metrics — estimate
    95|        "hermes" => 0.280,  // hermes organ health/cycles — estimate
    96|        _ => 0.300,         // general fallback
    97|    };
    98|    (raw_q / domain_p50).min(1.0)
    99|}
   100|
   101|/// Observe a crystal from a verdict — the critical link in the compound loop.
   102|///
   103|/// Called from BOTH the pipeline (user /judge) and nightshift (background).
   104|/// Unifying these paths ensures all crystal observations go through the same
   105|/// gates (quorum, epistemic, KNN merge) regardless of origin.
   106|///
   107|/// Uses semantic merge (cosine ≥ 0.75) to accumulate on existing crystals
   108|/// instead of creating fragmented duplicates.
   109|///
   110|/// **Epistemic soft gate** (widened 2026-04-26): verdicts with high Dog disagreement
   111|/// are weighted down to prevent crystal poisoning. Three tiers:
   112|///
   113|///   - Agreed   (disagree < φ⁻²): full weight (1.0)
   114|///   - Disputed (φ⁻² ≤ disagree < φ⁻¹): linear decay 1.0→0.0
   115|///   - Contested (disagree ≥ φ⁻¹): quarantined — zero crystal update
   116|pub(crate) async fn observe_crystal_for_verdict(
   117|    verdict: &crate::domain::dog::Verdict,
   118|    stimulus_embedding: &Option<Embedding>,
   119|    domain: &str,
   120|    deps: &PipelineDeps<'_>,
   121|) {
   122|    observe_crystal_for_verdict_core(
   123|        verdict,
   124|        stimulus_embedding,
   125|        domain,
   126|        deps.storage,
   127|        deps.metrics,
   128|        deps.event_tx,
   129|    )
   130|    .await;
   131|}
   132|
   133|/// Core crystal observation logic — usable by both pipeline and nightshift.
   134|///
   135|/// Separated from PipelineDeps so nightshift can call it directly with
   136|/// its own storage/metrics/event_tx, without constructing a full PipelineDeps.
   137|pub async fn observe_crystal_for_verdict_core(
   138|    verdict: &crate::domain::dog::Verdict,
   139|    stimulus_embedding: &Option<Embedding>,
   140|    domain: &str,
   141|    storage: &dyn crate::domain::storage::StoragePort,
   142|    metrics: &crate::domain::metrics::Metrics,
   143|    event_tx: Option<&tokio::sync::broadcast::Sender<KernelEvent>>,
   144|) {
   145|    // ── Source gate: only crystallize domains with external content ──
   146|    // Crystals are the organism's long-term memory. Only domain-relevant
   147|    // content that helps Dogs judge future stimuli should crystallize.
   148|    // Audit (2026-05-14): 70% of crystals were noise — commit messages (47%),
   149|    // session logs (13%), kernel anomalies (10%). None help Dogs judge tokens
   150|    // or chess positions. Nightshift still JUDGES all observations (verdicts
   151|    // remain for metrics), but only external-content domains CRYSTALLIZE.
   152|    //
   153|    // CHAOS approach: strict whitelist now, loosen when crystal A/B test
   154|    // shows domain X improves judgment. Filtering too much > crystallizing poison.
   155|    if !is_crystallizable_domain(domain) {
   156|        metrics.inc_domain_gate_skipped();
   157|        tracing::debug!(
   158|            phase = "crystal_gate",
   159|            %domain,
   160|            "non-crystallizable domain — verdict recorded, crystal skipped"
   161|        );
   162|        return;
   163|    }
   164|
   165|    // ── EPOCHÉ gate — suspension verdict must NOT crystallize ──
   166|    // Dogs are in equipollence: no crystallization until the disagreement resolves.
   167|    if matches!(verdict.kind, crate::domain::dog::VerdictKind::Epoche) {
   168|        tracing::info!(
   169|            phase = "crystal_skip",
   170|            reason = "epoche_suspension",
   171|            "EPOCHÉ verdict — Dogs in equipollence, skipping crystallization"
   172|        );
   173|        return;
   174|    }
   175|
   176|    // ── T8+T9: Quorum gate — single-Dog verdicts must NOT crystallize ──
   177|    // Verdict is still SERVED (availability), but only consensus crystallizes (integrity).
   178|    if verdict.voter_count < crate::domain::dog::MIN_QUORUM {
   179|        tracing::info!(
   180|            phase = "crystal_gate",
   181|            voter_count = verdict.voter_count,
   182|            min_quorum = crate::domain::dog::MIN_QUORUM,
   183|            "quorum not met — crystal observation skipped (verdict still served)"
   184|        );
