   250|        // Chess works because moves repeat exactly; dev/token/session never do.
   251|        let slug = ccm::semantic_slug(domain, &verdict.stimulus_summary);
   252|        tracing::info!(
   253|            phase = "crystal_merge",
   254|            %slug,
   255|            "no embedding available, using semantic slug + FNV hash"
   256|        );
   257|        (
   258|            format!("{:x}", ccm::content_hash(&ccm::normalize_for_hash(&slug))),
   259|            true,
   260|        )
   261|    };
   262|
   263|    let now = chrono::Utc::now().to_rfc3339();
   264|    // Normalize Q-Score: raw scores are φ-bounded (max ≈ 0.618).
   265|    // Without normalization, no crystal can ever reach the 0.618 crystallization threshold.
   266|    // Apply domain-specific calibration (2026-05-12): chess vs twitter have different p50.
   267|    // Then apply epistemic weight: disputed verdicts contribute less to crystal confidence.
   268|    let raw_q = verdict.q_score.total;
