   287|        crate::domain::dog::VerdictKind::Wag => "wag",
   288|        crate::domain::dog::VerdictKind::Growl => "growl",
   289|        crate::domain::dog::VerdictKind::Bark => "bark",
   290|        crate::domain::dog::VerdictKind::Epoche => "epoche",
