   293|        .observe_crystal(
   294|            &crystal_id,
   295|            &verdict.stimulus_summary,
   296|            domain,
   297|            crystal_confidence,
   298|            &now,
   299|            verdict.voter_count,
   300|            &verdict.id,
   301|            verdict_kind,
   302|        )
