   310|            action = "observed",
   311|            crystal_id = %crystal_id,
   312|            domain = %domain,
   313|            confidence = %format!("{:.3}", crystal_confidence),
   314|            polarity = %verdict_kind,
   315|            voters = verdict.voter_count,
   316|            epistemic = %epistemic_tag,
